SELECT task.*
FROM order_delivery_task AS task
WHERE task.tenant_id = #{tenantId}
  AND task.order_id = #{orderId}
  AND task.del_flag = '0'
LIMIT 1

SELECT task.*
FROM order_delivery_task AS task
WHERE task.tenant_id = #{tenantId}
  AND task.id = #{id}
  AND task.del_flag = '0'
LIMIT 1

SELECT task.*
FROM order_delivery_task AS task
WHERE task.tenant_id = #{tenantId}
  AND task.assignee_id = #{assigneeId}
  AND task.id = #{id}
  AND task.del_flag = '0'
LIMIT 1

mapper.update:
UPDATE order_delivery_task
SET status = 'ASSIGNED',
    assignee_id = #{staff.id},
    assignee_name = #{staff.nickname},
    assignee_mobile = #{staff.phone},
    assigned_by = #{operatorId},
    assigned_by_name = #{operatorName},
    version = version + 1,
    update_by = #{operatorId},
    update_time = #{operateTime}
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND status = #{expectedStatus}
  AND version = #{version}
  AND del_flag = '0'

UPDATE order_delivery_task
SET status = #{targetStatus},
    exception_code = COALESCE(#{reasonCode}, exception_code),
    exception_summary = COALESCE(#{description}, exception_summary),
    version = version + 1,
    update_by = #{operatorId},
    update_time = #{operateTime},

        return_pending_at = #{operateTime}
        returned_at = #{operateTime}, closed_at = #{operateTime}
        closed_at = #{operateTime}

WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND status = #{expectedStatus}
  AND version = #{version}
  AND del_flag = '0'

UPDATE order_delivery_task
SET status = #{targetStatus},
    version = version + 1,
    update_by = #{assigneeId},
    update_time = #{operateTime}
    , picking_started_at = #{operateTime}
    , picked_up_at = #{operateTime}
    , delivered_at = #{operateTime}
WHERE tenant_id = #{tenantId}
  AND assignee_id = #{assigneeId}
  AND id = #{id}
  AND status = #{expectedStatus}
  AND version = #{version}
  AND del_flag = '0'

UPDATE order_delivery_task
SET status = 'EXCEPTION',
    exception_code = #{reasonCode},
    exception_summary = #{description},
    version = version + 1,
    update_by = #{assigneeId},
    update_time = #{operateTime}
WHERE tenant_id = #{tenantId}
  AND assignee_id = #{assigneeId}
  AND id = #{id}
  AND status = #{expectedStatus}
  AND version = #{version}
  AND del_flag = '0'
